package org.updraft.betterstatus.protocol;
import org.updraft.betterstatus.model.*; import java.io.*; import java.util.*;
public final class StatusProtocol { public static final String SUBCHANNEL="srvstatus"; public static final int VERSION=1,MAX_SERVERS=512,MAX_PACKET=30000; private StatusProtocol(){} public static byte[] encode(Collection<ServerSnapshot> list,String online,String offline,String maintenance)throws IOException{if(list.size()>MAX_SERVERS)throw new IOException("Too many servers");ByteArrayOutputStream b=new ByteArrayOutputStream();try(DataOutputStream o=new DataOutputStream(b)){o.writeUTF(SUBCHANNEL);o.writeInt(VERSION);o.writeInt(list.size());for(ServerSnapshot s:list){o.writeUTF(s.name());o.writeUTF(s.maintenance()?maintenance:switch(s.state()){case ONLINE,STARTING->online;case MAINTENANCE->maintenance;case DEGRADED->"§eDegraded";case OFFLINE,UNREACHABLE,RESTARTING->offline;default->"§7Unknown";});o.writeUTF(s.state().name());o.writeInt(s.players());o.writeInt(s.maxPlayers());o.writeLong(s.pingMillis());o.writeUTF(limit(s.motd(),1024));o.writeUTF(limit(s.version(),128));o.writeLong(s.uptimeSeconds());o.writeLong(s.downtimeSeconds());o.writeLong(s.lastSuccessMillis());}}if(b.size()>MAX_PACKET)throw new IOException("Packet too large");return b.toByteArray();} public static List<WireStatus> decode(byte[] data)throws IOException{if(data==null||data.length>MAX_PACKET)throw new IOException("Invalid packet size");try(DataInputStream in=new DataInputStream(new ByteArrayInputStream(data))){if(!SUBCHANNEL.equals(in.readUTF())||in.readInt()!=VERSION)throw new IOException("Unsupported packet");int n=in.readInt();if(n<0||n>MAX_SERVERS)throw new IOException("Invalid count");List<WireStatus> out=new ArrayList<>(n);for(int i=0;i<n;i++)out.add(new WireStatus(in.readUTF(),in.readUTF(),ServerState.valueOf(in.readUTF()),in.readInt(),in.readInt(),in.readLong(),in.readUTF(),in.readUTF(),in.readLong(),in.readLong(),in.readLong()));if(in.available()!=0)throw new IOException("Trailing data");return out;}catch(EOFException|IllegalArgumentException e){throw new IOException("Malformed status packet",e);}}private static String limit(String s,int n){return s==null?"":s.substring(0,Math.min(s.length(),n));} public record WireStatus(String name,String legacyStatus,ServerState state,int players,int maxPlayers,long pingMillis,String motd,String version,long uptimeSeconds,long downtimeSeconds,long lastSuccessMillis){} }